// tmavsia farba obrysu z farby vyplne
function tmava(h) {
  const n = parseInt(h.slice(1), 16), f = v => Math.round(v * 0.32 + 14).toString(16).padStart(2, '0');
  return '#' + f(n >> 16) + f((n >> 8) & 255) + f(n & 255);
}
const telo = t => VLASTNE[t] ?? `<path d="${T[t] ?? ''}"/>`;
const vrstva = ([t, farba, m = 1, x = 0, y = 0]) =>
  `<g transform="translate(${x} ${y}) scale(${m})" fill="${farba}" stroke="${tmava(farba)}" stroke-width="${34 / m}">${telo(t)}</g>`;

export function ik(tvar, farba = '#c8b89a', ...vrstvy) {
  if (!T[tvar] && !VLASTNE[tvar]) console.warn('Neznama ikona', tvar);
  return `<svg class="ik" viewBox="-30 -30 572 572" stroke-linejoin="round" paint-order="stroke">`
    + vrstva([tvar, farba]) + vrstvy.map(vrstva).join('') + '</svg>';
}

// male znacky v pravom dolnom rohu
export const PECENE = ['fire', '#ff9a3a', 0.46, 290, 290];   // upecene na ohni
export const SUSENE = ['sun', '#ffd24a', 0.46, 290, 290];    // ususene na slnku

// ikony rozhrania (HUD, spravy)
export const UI = {
  srdce: ik('hearts', '#e8473c'),
  jedlo: ik('meat', '#d0804a'),
  voda: ik('water-drop', '#4aa8ea'),
  dennik: ik('scroll-unfurled', '#e2cf9e'),
  zamok: ik('padlock', '#b8b2a6'),
  ohen: ik('campfire', '#ef7a2f'),
  drevo: ik('log', '#b07a45'),
  hamaka: ik('hamaka', '#c9a06a'),
  lod: ik('wood-canoe', '#b07a45'),
};

// v HTML: <span data-ik="srdce"></span> sa nahradi ikonou
for (const el of document.querySelectorAll('[data-ik]')) el.innerHTML = UI[el.dataset.ik] ?? '';
